local function make(class, props, parent)
    local obj = Instance.new(class)
    for k, v in pairs(props or {}) do obj[k] = v end
    obj.Parent = parent
    return obj
end
local iconCache={}
local base64Alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local base64Values={}
for i=1,#base64Alphabet do base64Values[base64Alphabet:sub(i,i)]=i-1 end
local function decodeBase64(data)
    local result={}
    for i=1,#data,4 do
        local a,b,c,d=data:sub(i,i),data:sub(i+1,i+1),data:sub(i+2,i+2),data:sub(i+3,i+3)
        local value=(base64Values[a] or 0)*262144+(base64Values[b] or 0)*4096+(base64Values[c] or 0)*64+(base64Values[d] or 0)
        table.insert(result,string.char(math.floor(value/65536)%256))
        if c~="=" and c~="" then table.insert(result,string.char(math.floor(value/256)%256)) end
        if d~="=" and d~="" then table.insert(result,string.char(value%256)) end
    end
    return table.concat(result)
end
local function iconAsset(name)
    if iconCache[name]~=nil then return iconCache[name] or nil end
    iconCache[name]=false
    if not capabilities.icons or not ICON_DATA[name] then return nil end
    local ok,asset=pcall(function()
        local path="ISBMenu-icon-v2-"..name..".png"
        if type(isfile)~="function" or not isfile(path) then writefile(path,decodeBase64(ICON_DATA[name])) end
        local loader=type(getcustomasset)=="function" and getcustomasset or getsynasset
        return loader(path)
    end)
    if ok and type(asset)=="string" and asset~="" then iconCache[name]=asset; return asset end
end
local function imageIcon(parent,name,size,pos,color)
    local asset=iconAsset(name)
    if not asset then return nil end
    return make("ImageLabel",{BackgroundTransparency=1,Image=asset,ImageColor3=color or C.text,
        ScaleType=Enum.ScaleType.Fit,Position=pos or UDim2.fromOffset(0,0),Size=UDim2.fromOffset(size or 20,size or 20)},parent)
end
local function round(obj, radius)
    make("UICorner", {CornerRadius = UDim.new(0, radius or 12)}, obj)
end
local function stroke(obj)
    make("UIStroke", {Color = C.line, Thickness = 1, Transparency = 0.25}, obj)
end
local function animate(obj, props)
    if settings.reducedMotion then
        for k,v in pairs(props) do obj[k] = v end
    else
        Tween:Create(obj, TweenInfo.new(0.24, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), props):Play()
    end
end
local function label(parent, text, size, color, pos, dims)
    return make("TextLabel", {BackgroundTransparency = 1, Text = text, Font = Enum.Font.BuilderSans,
        TextSize = size or 14, TextColor3 = color or C.text, TextXAlignment = Enum.TextXAlignment.Left,
        Position = pos or UDim2.new(), Size = dims or UDim2.new(1,0,0,24)}, parent)
end
local function button(parent, text, pos, dims, fn)
    local b = make("TextButton", {Text = text, Font = Enum.Font.BuilderSansMedium, TextSize = 13,
        TextColor3 = C.text, BackgroundColor3 = C.card, AutoButtonColor = false,
        Position = pos or UDim2.new(), Size = dims or UDim2.fromOffset(100,32)}, parent)
    round(b, 8)
    connect(b.MouseEnter, function() animate(b, {BackgroundColor3 = C.line}) end)
    connect(b.MouseLeave, function() animate(b, {BackgroundColor3 = C.card}) end)
    connect(b.Activated, function()
        local ok, err = pcall(fn)
        if not ok then warn("ISB Menu: " .. tostring(err)); if notify then notify("Aktion konnte nicht ausgeführt werden.") end end
    end)
    return b
end
local function humanoid()
    return player.Character and player.Character:FindFirstChildOfClass("Humanoid")
end
local function root()
    return player.Character and player.Character:FindFirstChild("HumanoidRootPart")
end
local function remember(h)
    if h and not originals[h] then
        originals[h] = {WalkSpeed = h.WalkSpeed, JumpPower = h.JumpPower, JumpHeight = h.JumpHeight}
    end
end
local function applyMovement()
    local h = humanoid()
    if not h or not (state.speed or state.jump) then return end
    remember(h)
    if state.speed then
        if not originals[h].speedOwned then originals[h].WalkSpeed=h.WalkSpeed end
        originals[h].speedOwned=true; h.WalkSpeed = state.speedValue
    end
    if state.jump then
        if not originals[h].jumpOwned then originals[h].JumpPower=h.JumpPower; originals[h].JumpHeight=h.JumpHeight end
        originals[h].jumpOwned=true
        if h.UseJumpPower then h.JumpPower = state.jumpValue
        else h.JumpHeight = state.jumpValue * state.jumpValue / (2 * math.max(workspace.Gravity, 1)) end
    end
end
local function stopFly()
    for _,obj in ipairs(flyObjects) do obj:Destroy() end
    table.clear(flyObjects)
    if flyHumanoid and flyHumanoid.Parent then flyHumanoid.AutoRotate = flyAutoRotate end
    flyHumanoid, flyAutoRotate = nil, nil
end
local function startFly()
    stopFly()
    local r, h = root(), humanoid()
    if not r or not h or h.Health <= 0 then return end
    flyHumanoid, flyAutoRotate = h, h.AutoRotate
    h.AutoRotate = false
    local attachment = make("Attachment", {Name = "ISBFlyAttachment"}, r)
    local velocity = make("LinearVelocity", {Name = "ISBFlyVelocity", Attachment0 = attachment,
        RelativeTo = Enum.ActuatorRelativeTo.World, MaxForce = math.huge, VectorVelocity = Vector3.zero}, r)
    local orientation = make("AlignOrientation", {Name = "ISBFlyOrientation", Attachment0 = attachment,
        Mode = Enum.OrientationAlignmentMode.OneAttachment, MaxTorque = math.huge, Responsiveness = 20}, r)
    flyObjects = {velocity, orientation, attachment}
end
local function restoreCollisions()
    for part, original in pairs(collisions) do
        if part.Parent then part.CanCollide = original end
    end
    table.clear(collisions)
end
local function clearVisuals()
    for _, obj in pairs(highlights) do obj:Destroy() end
    for _, obj in pairs(tags) do obj:Destroy() end
    table.clear(highlights); table.clear(tags)
end
local function restoreCamera()
    local camera, h = workspace.CurrentCamera, humanoid()
    if spectating and next(spectateOriginal)==nil and camera and h then
        camera.CameraSubject=h; camera.CameraType=Enum.CameraType.Custom
    end
    for originalCamera,original in pairs(spectateOriginal) do
        if originalCamera.Parent then
            originalCamera.CameraSubject=(original.subject and original.subject.Parent) and original.subject or h
            originalCamera.CameraType=original.kind
        end
    end
    table.clear(spectateOriginal)
    spectating = nil
end
local function applyLighting()
    if state.fullbright or state.shadows then
        if not lightingOriginal then
            lightingOriginal = {Brightness = Lighting.Brightness, ClockTime = Lighting.ClockTime,
                Ambient = Lighting.Ambient, GlobalShadows = Lighting.GlobalShadows}
        end
        Lighting.Brightness = state.fullbright and 2 or lightingOriginal.Brightness
        Lighting.ClockTime = state.fullbright and 14 or lightingOriginal.ClockTime
        Lighting.Ambient = state.fullbright and Color3.fromRGB(180,180,180) or lightingOriginal.Ambient
        if state.shadows then Lighting.GlobalShadows=false else Lighting.GlobalShadows=lightingOriginal.GlobalShadows end
    elseif lightingOriginal then
        for k,v in pairs(lightingOriginal) do Lighting[k] = v end
        lightingOriginal = nil
    end
end

