local openRevision=0
setOpen=function(value)
    opened=value; openRevision=openRevision+1
    local revision=openRevision
    if value then
        window.Visible=true
        animate(motionScale,{Scale=1}); animate(window,{GroupTransparency=0,Position=UDim2.new(0.5,0,1,-72)})
    else
        animate(motionScale,{Scale=0.94}); animate(window,{GroupTransparency=1,Position=UDim2.new(0.5,0,1,-54)})
        task.delay(settings.reducedMotion and 0 or 0.25,function() if alive and revision==openRevision then window.Visible=false end end)
    end
    animate(backdropBlur,{Size=value and settings.blur and 12 or 0})
end
local pageRevision=0
selectPage=function(name)
    pageRevision=pageRevision+1
    local revision=pageRevision
    if page==name then setOpen(not opened); return end
    page=name; query=""; captureKey=false
    animate(window,{GroupTransparency=0.45}); animate(motionScale,{Scale=0.98})
    task.delay(settings.reducedMotion and 0 or 0.10,function()
        if not alive or revision~=pageRevision then return end
        render(); setOpen(true)
    end)
end

-- Each page has its own connections; rebuilding a page releases them.
local rowConnections = {}
local function rowConnect(signal, fn)
    local con = signal:Connect(fn); table.insert(rowConnections, con); return con
end
local function rowButton(parent, text, pos, dims, fn)
    local b = make("TextButton", {Text = text, Font = Enum.Font.BuilderSansMedium, TextSize = 12,
        TextColor3 = C.text, BackgroundColor3 = C.line, AutoButtonColor = true,
        Position = pos, Size = dims}, parent)
    round(b,8)
    rowConnect(b.Activated, function()
        local ok, err = pcall(fn)
        if not ok then warn("ISB Menu: " .. tostring(err)); notify("Aktion fehlgeschlagen.") end
    end)
    return b
end
local function card(text, desc, height)
    local f = make("CanvasGroup", {BackgroundColor3 = C.card, Size = UDim2.new(1,0,0,height or 80),GroupTransparency=1}, content)
