local function updateDashboard()
    local fields=dashboardRefs
    if fields.server then
        fields.server.value.Text=tostring(#Players:GetPlayers()).." / "..tostring(Players.MaxPlayers or "—").." Spieler"
        fields.server.sub.Text="Place "..tostring(game.PlaceId)
        local inServer=0
        for _,other in ipairs(Players:GetPlayers()) do if session.friends[other.UserId] then inServer=inServer+1 end end
        fields.friends.value.Text=tostring(inServer).." im Server"
        fields.friends.sub.Text=tostring(session.onlineFriends or "—").." online  ·  "..tostring(session.friendTotal or "—").." insgesamt"
        fields.executor.value.Text=session.executor
        fields.executor.sub.Text=session.executorVersion~="" and session.executorVersion or "Funktionen abhängig vom Executor"
        fields.session.value.Text=string.format("%02d:%02d",math.floor((os.clock()-startedAt)/60),math.floor(os.clock()-startedAt)%60).." Hub aktiv"
        fields.session.sub.Text=(game.PrivateServerId and game.PrivateServerId~="") and "Private Sitzung  ·  Region nicht verfügbar" or "Öffentliche Sitzung  ·  Region nicht verfügbar"
    end
end
local function drawCharacter()
    local grid=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,76)},content)
    local quick={{"fly","Fliegen","bolt",Color3.fromRGB(55,153,229)},{"noclip","Noclip","arrows-up-down",Color3.fromRGB(159,115,217)},
        {"infinitejump","Mehrfachsprung","arrow-path",Color3.fromRGB(71,192,150)},{"esp","Highlights","eye",Color3.fromRGB(232,164,64)}}
    for i,item in ipairs(quick) do
        local action=findAction(item[1]); local b
        b=rowButton(grid,"",UDim2.new((i-1)/4,(i-1)*3,0,0),UDim2.new(.25,-9,0,76),function()
            action.fn(); render()
        end)
        round(b,15); b.BackgroundColor3=action.get() and item[4]:Lerp(C.bg,.65) or C.card
        imageIcon(b,item[3],21,UDim2.fromOffset(13,12),item[4])
        label(b,item[2],11,C.text,UDim2.fromOffset(13,43),UDim2.new(1,-20,0,20))
        local dot=make("Frame",{BackgroundColor3=action.get() and item[4] or C.line,Position=UDim2.new(1,-17,0,15),Size=UDim2.fromOffset(5,5)},b)
        round(dot,3)
    end
    local tabs=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,30)},content)
    for i,item in ipairs({{"speedvalue","Speed"},{"jumpvalue","Jump"},{"flyspeed","Flight"},{"fovvalue","FOV"}}) do
        local b=rowButton(tabs,item[2],UDim2.fromOffset((i-1)*75,0),UDim2.fromOffset(66,28),function() tuning=item[1]; render() end)
        round(b,14); b.BackgroundColor3=tuning==item[1] and C.text or C.card; b.TextColor3=tuning==item[1] and C.bg or C.muted
    end
    rowButton(tabs,"Reset",UDim2.new(1,-70,0,0),UDim2.fromOffset(70,28),function()
        for _,id in ipairs({"speed","jump","fov"}) do local action=findAction(id); if action.get() then action.fn() end end
        render(); notify("Speed, Jump und Sichtfeld zurückgesetzt.","Charakter")
    end)
    local source=findAction(tuning); local action=table.clone(source)
    action.fn=function(value)
        source.fn(value)
        local enable=({speedvalue="speed",jumpvalue="jump",fovvalue="fov"})[tuning]
        if enable then local control=findAction(enable); if not control.get() then control.fn() end end
    end
    drawAction(action)
    local footer=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,34)},content)
    rowButton(footer,"Rejoin",UDim2.fromOffset(0,0),UDim2.fromOffset(110,32),rejoin)
