    rowButton(footer,"Respawn",UDim2.fromOffset(240,0),UDim2.fromOffset(110,32),function() local h=humanoid(); if h then h.Health=0 end end)
    for _,entry in ipairs(actions) do
        if entry.category=="Bewegung" and entry.kind=="button" then drawAction(entry) end
    end
end
local function drawServers()
    local control=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,36)},content)
    rowButton(control,"Aktualisieren",UDim2.fromOffset(0,0),UDim2.fromOffset(108,30),function() table.clear(servers.history); fetchServers(nil) end)
    rowButton(control,servers.sort=="Asc" and "Wenig Spieler" or "Viele Spieler",UDim2.fromOffset(118,0),UDim2.fromOffset(116,30),function()
        if servers.loading then return end
        servers.sort=servers.sort=="Asc" and "Desc" or "Asc"; table.clear(servers.history); fetchServers(nil)
    end)
    rowButton(control,"Rejoin",UDim2.fromOffset(244,0),UDim2.fromOffset(82,30),rejoin)
    rowButton(control,"Serverhop",UDim2.fromOffset(336,0),UDim2.fromOffset(98,30),serverHop)
    if servers.loading then plainCard("Server werden geladen …","Öffentliche Roblox-Server für diesen Place.",74)
    elseif servers.error then plainCard("Serverliste nicht verfügbar",servers.error,86)
    else
        for _,entry in ipairs(servers.data) do
            if matches(entry.id.." "..tostring(entry.playing)) then
                local current=entry.id==game.JobId; local full=entry.playing>=entry.maxPlayers
                local f=card(string.format("%d / %d Spieler%s",entry.playing,entry.maxPlayers,current and "  ·  Aktuell" or ""),
                    string.format("%s ms  ·  %s FPS  ·  %s",tostring(entry.ping or "—"),tostring(entry.fps or "—"),entry.id:sub(1,8)),68)
                imageIcon(f,"server-stack",20,UDim2.fromOffset(14,16),C.muted)
                for _,child in ipairs(f:GetChildren()) do if child:IsA("TextLabel") then child.Position=child.Position+UDim2.fromOffset(30,0); child.Size=UDim2.new(1,-175,0,24) end end
                local b=rowButton(f,current and "Aktuell" or (full and "Voll" or "Beitreten"),UDim2.new(1,-110,0,18),UDim2.fromOffset(96,30),function()
                    if not current and not full then joinServer(entry.id) end
                end)
                if current or full then b.TextColor3=C.muted end
            end
        end
        if #servers.data==0 and servers.loaded then plainCard("Keine öffentlichen Server gefunden","Private Server werden von dieser API nicht aufgelistet.",76) end
    end
    local pagination=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,34)},content)
    rowButton(pagination,"Zurück",UDim2.fromOffset(0,0),UDim2.fromOffset(90,30),function()
        if servers.loading or #servers.history==0 then return end
        local previous=table.remove(servers.history); fetchServers(previous~=false and previous or nil)
    end)
    label(pagination,"Seite "..tostring(#servers.history+1),12,C.muted,UDim2.fromOffset(105,4),UDim2.fromOffset(94,22))
    rowButton(pagination,"Weiter",UDim2.fromOffset(200,0),UDim2.fromOffset(90,30),function()
        if servers.loading or not servers.nextCursor then return end
        table.insert(servers.history,servers.cursor or false); fetchServers(servers.nextCursor)
    end)
    local details=plainCard("Diese Sitzung",string.format("Place %s  ·  Universe %s\nJob-ID: %s",tostring(game.PlaceId),tostring(game.GameId or "—"),tostring(game.JobId or "—")),104)
    rowButton(details,"Join-Script kopieren",UDim2.fromOffset(16,74),UDim2.fromOffset(168,26),function()
        copyText(string.format('game:GetService("TeleportService"):TeleportToPlaceInstance(%s, %q, game:GetService("Players").LocalPlayer)\n-- by Larsiopuw',tostring(game.PlaceId),tostring(game.JobId or "")))
    end)
end
