                local tile=rowButton(pair,"",UDim2.new(col*.5,col*5,0,0),UDim2.new(.5,-5,0,120),function() loadScriptSource(entry) end)
                round(tile,14); tile.BackgroundColor3=C.card
                imageIcon(tile,"code-bracket-square",24,UDim2.fromOffset(14,13),C.muted)
                local titleLabel=label(tile,entry.title,12,C.text,UDim2.fromOffset(14,48),UDim2.new(1,-28,0,34))
                titleLabel.TextWrapped=true; titleLabel.TextYAlignment=Enum.TextYAlignment.Top
                local gameLabel=label(tile,entry.game,10,C.muted,UDim2.fromOffset(14,89),UDim2.new(1,-28,0,16))
                gameLabel.TextTruncate=Enum.TextTruncate.AtEnd
                if entry.verified then label(tile,"VERIFIZIERT",8,C.good,UDim2.new(1,-95,0,18),UDim2.fromOffset(82,16)) end
            end
        end
    end
    local paging=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,32)},content)
    rowButton(paging,"Zurück",UDim2.fromOffset(0,0),UDim2.fromOffset(90,30),function() if scriptSearch.page>1 then searchRemoteScripts(scriptSearch.page-1) end end)
    label(paging,tostring(scriptSearch.page).." / "..tostring(scriptSearch.totalPages),11,C.muted,UDim2.fromOffset(105,4),UDim2.fromOffset(80,20))
    rowButton(paging,"Weiter",UDim2.fromOffset(196,0),UDim2.fromOffset(90,30),function() if scriptSearch.page<scriptSearch.totalPages then searchRemoteScripts(scriptSearch.page+1) end end)
    local footer=label(content,scriptSearch.provider=="RScripts" and "Powered by Rscripts.net" or "Quelle: "..scriptSearch.provider,10,C.muted,UDim2.new(),UDim2.new(1,0,0,18))
end
local function drawPlayers()
    for _,other in ipairs(Players:GetPlayers()) do
        if other ~= player and matches(other.DisplayName .. " " .. other.Name) then
            local f=card(other.DisplayName,"@" .. other.Name,104)
            for _,child in ipairs(f:GetChildren()) do
                if child:IsA("TextLabel") then child.Position=UDim2.fromOffset(70,child.Position.Y.Offset); child.Size=UDim2.new(1,-86,0,child.Size.Y.Offset) end
            end
            local avatar=make("ImageLabel",{BackgroundColor3=C.panel,Image="",Position=UDim2.fromOffset(14,12),Size=UDim2.fromOffset(40,40)},f)
            round(avatar,20)
            task.spawn(function()
                local ok,url=pcall(function() return Players:GetUserThumbnailAsync(other.UserId,Enum.ThumbnailType.HeadShot,Enum.ThumbnailSize.Size100x100) end)
                if alive and avatar.Parent and ok then avatar.Image=url end
            end)
            rowButton(f,"Beobachten",UDim2.fromOffset(16,68),UDim2.fromOffset(112,26),function()
                local h=other.Character and other.Character:FindFirstChildOfClass("Humanoid")
                if h and workspace.CurrentCamera then
                    local camera=workspace.CurrentCamera
                    if not spectateOriginal[camera] then
                        spectateOriginal[camera]={subject=camera.CameraSubject,kind=camera.CameraType}
                    end
                    spectating=other; workspace.CurrentCamera.CameraSubject=h; workspace.CurrentCamera.CameraType=Enum.CameraType.Custom
                    notify("Beobachtung: " .. other.DisplayName)
                else notify("Charakter ist noch nicht verfügbar.") end
            end)
            rowButton(f,"Zum Spieler",UDim2.fromOffset(138,68),UDim2.fromOffset(112,26),function()
                local target=other.Character and other.Character:FindFirstChild("HumanoidRootPart")
                local r=root()
                if target and r then r.CFrame=target.CFrame*CFrame.new(3,0,0); notify("Position lokal geändert.")
                else notify("Charakter ist noch nicht verfügbar.") end
            end)
        end
    end
end
render = function()
    if not alive then return end
    clearRows()
    pageTitle.Text=page == "Start" and "ISB Menu" or page
    subtitle.Text=descriptions[page] or "Eigene Erweiterungen"
    local remote=page=="Skripte" and not scriptSearch.localMode
    local searchable=page~="Start" and page~="Musik" and page~="Einstellungen" and page~="Voice"
    search.Visible=searchable
    search.PlaceholderText=remote and "Skripte suchen …" or "Funktionen und Spieler suchen …"
    content.Position=UDim2.fromOffset(18,searchable and 104 or 60)
    content.Size=UDim2.new(1,-36,1,searchable and -124 or -80)
    local desired=remote and scriptSearch.query or query
    if search.Text ~= desired then
        updatingSearch=true; search.Text=desired; updatingSearch=false
    end
    local heights={Start=398,Bewegung=390,Spieler=400,Server=420,Darstellung=400,Skripte=420,Musik=420,Favoriten=400,Einstellungen=400,Voice=390}
    animate(window,{Size=UDim2.fromOffset(600,heights[page] or 400)})
    for _,child in ipairs(headerIcon:GetChildren()) do child:Destroy() end
    local pageIndex=table.find(navNames,page) or 9
    imageIcon(headerIcon,page=="Voice" and "microphone" or navAssetNames[pageIndex],20,UDim2.new(),C.text)
    for name,b in pairs(navButtons) do
        b.TextColor3=name == page and C.accent or C.muted
        b.BackgroundColor3=name == page and C.card or C.panel
        for _,part in ipairs(navIcons[name]) do part.obj[part.property]=name==page and C.accent or C.muted end
    end
    indicator.BackgroundColor3=C.accent
    animate(indicator,{Position=UDim2.fromOffset(88+((table.find(navNames,page) or 9)-1)*46,47)})
    if page == "Start" then
        drawDashboard(); updateDashboard()
    elseif page=="Bewegung" and query=="" then
        drawCharacter()
    elseif page=="Server" and query=="" then
        drawServers()
        if not servers.loaded and not servers.loading and not servers.error then fetchServers(nil) end
    elseif page=="Voice" then
        drawVoice()
    elseif page=="Skripte" then
        if scriptSearch.localMode then drawScripts() else drawScriptSearch() end
    elseif page == "Musik" and query == "" then
        local f=card("Deine Musik","Roblox-Audio-ID eingeben. Das Asset muss im Spiel verwendbar sein.",154)
        local input=make("TextBox",{Text="",PlaceholderText="Audio-ID",ClearTextOnFocus=false,Font=Enum.Font.BuilderSans,
            TextSize=13,TextColor3=C.text,PlaceholderColor3=C.muted,BackgroundColor3=C.panel,
            Position=UDim2.fromOffset(16,77),Size=UDim2.new(1,-32,0,30)},f)
        round(input,8)
        rowButton(f,"Abspielen",UDim2.fromOffset(16,115),UDim2.fromOffset(108,28),function()
            local id=input.Text:match("^%s*(%d+)%s*$")
            if not id or #id > 18 then notify("Bitte eine gültige numerische Audio-ID eingeben."); return end
            table.insert(musicQueue,id); playQueue(#musicQueue)
            showWidget("music")
            notify("Audio angefordert. Freigabe und Ladezeit hängen vom Asset ab.")
            render()
        end)
        rowButton(f,"Pause / Weiter",UDim2.fromOffset(134,115),UDim2.fromOffset(122,28),function()
            if sound.IsPlaying then sound:Pause() else sound:Resume() end
        end)
        rowButton(f,"Stop",UDim2.fromOffset(266,115),UDim2.fromOffset(72,28),function() sound:Stop() end)
        local queue=plainCard("Warteschlange",#musicQueue==0 and "Noch keine Audio-IDs hinzugefügt." or table.concat(musicQueue,"  ·  "),112)
        rowButton(queue,"Zurück",UDim2.fromOffset(16,74),UDim2.fromOffset(88,28),function() playQueue(queueIndex-1) end)
        rowButton(queue,"Weiter",UDim2.fromOffset(114,74),UDim2.fromOffset(88,28),function() playQueue(queueIndex+1) end)
        rowButton(queue,"Leeren",UDim2.fromOffset(212,74),UDim2.fromOffset(88,28),function() sound:Stop(); table.clear(musicQueue); queueIndex=0; render() end)
        drawAction({id="volume",name="Lautstärke",desc="Nur die Musik von ISB Menu",kind="slider",
            min=0,max=100,step=5,get=function() return math.floor(sound.Volume*100+0.5) end,fn=function(v) sound.Volume=v/100 end})
        local clockCard=card("Timer und Stoppuhr","Eine kompakte Aktivitätsanzeige bleibt oberhalb des Spiels sichtbar.",150)
        local minutes=make("TextBox",{Text="5",PlaceholderText="Minuten",ClearTextOnFocus=false,
            Font=Enum.Font.BuilderSans,TextSize=13,TextColor3=C.text,BackgroundColor3=C.panel,
            Position=UDim2.fromOffset(16,78),Size=UDim2.fromOffset(64,28)},clockCard)
        round(minutes,8)
        rowButton(clockCard,"Timer starten",UDim2.fromOffset(90,78),UDim2.fromOffset(128,28),function()
            local value=tonumber(minutes.Text)
            if not value or value~=value or value<0.1 or value>180 then notify("Timer: 0,1 bis 180 Minuten eingeben (z. B. 5). "); return end
            timer.duration=value*60; timer.remaining=timer.duration; timer.running=true; showWidget("timer")
        end)
        rowButton(clockCard,"Stoppuhr",UDim2.fromOffset(228,78),UDim2.fromOffset(100,28),function()
            stopwatch.elapsed=0; stopwatch.running=true; showWidget("stopwatch")
        end)
        label(clockCard,"Pause und Beenden direkt im Widget.",10,C.muted,UDim2.fromOffset(16,116),UDim2.new(1,-32,0,22))
    elseif page == "Einstellungen" and query == "" then
        if settingsSection==nil then
            local categories={{"Allgemein","cog-6-tooth"},{"Tasten","command-line"},{"Performance","bolt"},{"Erkennung","shield-check"},{"Protokoll","document-text"}}
            local grid=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,248)},content)
            for i,entry in ipairs(categories) do
                local b=rowButton(grid,"",UDim2.new(((i-1)%3)/3,((i-1)%3)*3,0,math.floor((i-1)/3)*122),UDim2.new(1/3,-8,0,112),function() settingsSection=entry[1]; render() end)
                round(b,18); imageIcon(b,entry[2],24,UDim2.fromOffset(16,17),C.muted)
                label(b,entry[1],13,C.text,UDim2.fromOffset(16,73),UDim2.new(1,-32,0,24))
            end
        else
        local back=make("Frame",{BackgroundTransparency=1,Size=UDim2.new(1,0,0,32)},content)
        rowButton(back,"← Einstellungen",UDim2.new(),UDim2.fromOffset(148,28),function() settingsSection=nil; render() end)
        if settingsSection=="Protokoll" then
            if #session.logs==0 then plainCard("Keine Einträge","Hinweise und Aktionen erscheinen hier.",78) end
            for _,entry in ipairs(session.logs) do plainCard(entry.time.."  ·  "..entry.title,entry.message,78) end
        elseif settingsSection=="Erkennung" then
            plainCard("Freunde und Staff","Freunde werden anhand deiner Freundesliste erkannt. Staff-Hinweise verwenden ausschließlich die konfigurierten User-IDs; sie sind kein Schutz vor Moderation.",106)
            plainCard("Executor",session.executor.." "..session.executorVersion,78)
            plainCard("Fähigkeiten",string.format("Dateien: %s  ·  Clipboard: %s  ·  Asset-Icons: %s",tostring(capabilities.files),tostring(capabilities.clipboard),tostring(capabilities.icons)),82)
        elseif settingsSection=="Performance" then
            drawAction({id="motion",name="Weniger Animationen",desc="Direkte Übergänge",kind="toggle",get=function() return settings.reducedMotion end,fn=function() settings.reducedMotion=not settings.reducedMotion; save() end})
            drawAction({id="blur",name="Hintergrund weichzeichnen",desc="Nur während das Menü geöffnet ist",kind="toggle",get=function() return settings.blur end,fn=function() settings.blur=not settings.blur; save(); setOpen(opened) end})
            plainCard("Live-Messung",tostring(session.fps).." FPS  ·  "..tostring(session.ping or "—").." ms\nDie Werte stehen auch in der Kopfzeile.",88)
        else
        local f=card("Akzentfarbe","Graphit mit deinem bevorzugten Farbakzent",104)
        for i,name in ipairs({"Neutral","Blue","Mint","Amber"}) do
            local b=rowButton(f,name,UDim2.fromOffset(16+(i-1)*104,68),UDim2.fromOffset(94,26),function()
                settings.theme=name; C.accent=themes[name]; save()
                logo.TextColor3=C.accent; launcher.TextColor3=C.accent; content.ScrollBarImageColor3=C.accent
                for _,h in pairs(highlights) do h.FillColor=C.accent end
                render()
            end)
            b.TextColor3=themes[name]
        end
        local k=card("Menü-Taste", "Anklicken, dann eine Taste drücken. Escape bricht ab.")
        local kb
        kb=rowButton(k,CONFIG.ToggleKey.Name,UDim2.new(1,-146,0,24),UDim2.fromOffset(130,32),function()
            captureKey=true; kb.Text="Taste drücken …"
        end)
        drawAction({id="motion",name="Weniger Animationen",desc="Direkte Übergänge",kind="toggle",
            get=function() return settings.reducedMotion end,fn=function() settings.reducedMotion=not settings.reducedMotion; save() end})
        drawAction({id="blur",name="Hintergrund weichzeichnen",desc="Nur während das Menü geöffnet ist",kind="toggle",
            get=function() return settings.blur end,fn=function() settings.blur=not settings.blur; save(); setOpen(opened) end})
        local voice=card("Voice Chat","Status, Mikrofon und Verbindung prüfen",78)
        rowButton(voice,"Öffnen",UDim2.new(1,-120,0,24),UDim2.fromOffset(104,32),function() query=""; selectPage("Voice") end)
        local s=card("Einstellungen speichern",type(writefile)=="function" and "Favoriten, Farbe und Taste werden lokal gespeichert." or "Dieser Executor bietet keinen Dateizugriff. Einstellungen gelten für diese Sitzung.")
        rowButton(s,"Speichern",UDim2.new(1,-120,0,24),UDim2.fromOffset(104,32),function() notify(save() and "Einstellungen gespeichert." or "Speichern nicht verfügbar.") end)
        local exit=card("Hub beenden","Aktive Funktionen zurücksetzen und Oberfläche entfernen.")
        rowButton(exit,"Beenden",UDim2.new(1,-120,0,24),UDim2.fromOffset(104,32),function() env.ISBMenu.Destroy() end)
        end
        end
    else
        local count=0
        for _,action in ipairs(actions) do
            local include=query ~= "" or action.category==page or (page=="Favoriten" and settings.favorites[action.id])
            if include and matches(action.name .. " " .. action.desc .. " " .. action.category) then drawAction(action); count=count+1 end
        end
        if page=="Spieler" then drawPlayers() end
        if count==0 and page~="Spieler" then card("Noch nichts gefunden", page=="Favoriten" and "Mit dem Stern an einer Funktion fügst du sie hier hinzu." or "Versuche einen anderen Suchbegriff.") end
    end
end
connect(search:GetPropertyChangedSignal("Text"),function()
    if updatingSearch then return end
    if page=="Skripte" and not scriptSearch.localMode then scriptSearch.query=search.Text; return end
    query=string.lower(search.Text); render()
end)
connect(search.FocusLost,function(enterPressed)
    if enterPressed and page=="Skripte" and not scriptSearch.localMode then searchRemoteScripts(1) end
end)
connect(UIS.JumpRequest,function()
    local h=humanoid()
    if state.infiniteJump and not UIS:GetFocusedTextBox() and h and h.Health>0 then h:ChangeState(Enum.HumanoidStateType.Jumping) end
end)
connect(UIS.InputBegan,function(input,processed)
    if captureKey and input.UserInputType==Enum.UserInputType.Keyboard then
        captureKey=false
        if input.KeyCode~=Enum.KeyCode.Escape and input.KeyCode~=Enum.KeyCode.Unknown then
            CONFIG.ToggleKey=input.KeyCode; settings.key=input.KeyCode.Name; save()
        end
        render(); return
    end
    if not processed and not UIS:GetFocusedTextBox() and input.KeyCode==CONFIG.ToggleKey then setOpen(not opened) end
end)
local drag
connect(header.InputBegan,function(input)
    if input.UserInputType==Enum.UserInputType.MouseButton1 or input.UserInputType==Enum.UserInputType.Touch then
        drag={input=input,origin=Vector2.new(input.Position.X,input.Position.Y),position=host.Position}
    end
end)
connect(UIS.InputChanged,function(input)
    local movingMouse=input.UserInputType==Enum.UserInputType.MouseMovement
    if activeSlider and (movingMouse or input==activeSlider.input) then activeSlider.update(input.Position.X) end
    if drag and (movingMouse or input==drag.input) then
        local delta=Vector2.new(input.Position.X,input.Position.Y)-drag.origin
        local vp=workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(800,600)
        local half=host.AbsoluteSize/2
        local x=math.clamp(drag.position.X.Scale*vp.X+drag.position.X.Offset+delta.X,half.X,vp.X-half.X)
        local y=math.clamp(drag.position.Y.Scale*vp.Y+drag.position.Y.Offset+delta.Y,host.AbsoluteSize.Y,vp.Y)
        host.Position=UDim2.fromOffset(x,y)
    end
end)
connect(UIS.InputEnded,function(input)
    if input.UserInputType==Enum.UserInputType.MouseButton1 or (activeSlider and input==activeSlider.input) then activeSlider=nil end
    if input.UserInputType==Enum.UserInputType.MouseButton1 or (drag and input==drag.input) then drag=nil end
end)
connect(Run.Stepped,function()
    if state.noclip and player.Character then
        for _,part in ipairs(player.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                if collisions[part]==nil then collisions[part]=part.CanCollide end
                part.CanCollide=false
            end
        end
    end
end)
local visualTimer, fpsTime, frames = 0,0,0
local lastViewport, lastCamera = nil,nil
connect(Run.RenderStepped,function(dt)
    if timer.running then
        timer.remaining=math.max(0,timer.remaining-dt)
        if timer.remaining==0 then timer.running=false; notify("ISB / Timer abgelaufen.") end
    end
    if stopwatch.running then stopwatch.elapsed=stopwatch.elapsed+dt end
    if widget.Visible then
        widgetValue.TextColor3=C.accent; widgetFill.BackgroundColor3=C.accent
        if widgetMode=="timer" then
            widgetTitle.Text=timer.running and "ISB / TIMER" or "ISB / TIMER PAUSIERT"
            widgetValue.Text=timeString(timer.remaining)
            widgetFill.Size=UDim2.fromScale(timer.duration>0 and timer.remaining/timer.duration or 0,1)
        elseif widgetMode=="stopwatch" then
            widgetTitle.Text=stopwatch.running and "ISB / STOPPUHR" or "ISB / STOPPUHR PAUSIERT"
            widgetValue.Text=timeString(stopwatch.elapsed) .. string.format(".%02d",math.floor(stopwatch.elapsed*100)%100)
            widgetFill.Size=UDim2.fromScale((stopwatch.elapsed%60)/60,1)
        else
            widgetTitle.Text=sound.IsPlaying and "ISB / AUDIO" or "ISB / AUDIO PAUSIERT"
            widgetValue.Text=timeString(sound.TimePosition) .. " / " .. timeString(sound.TimeLength)
            widgetFill.Size=UDim2.fromScale(sound.TimeLength>0 and math.clamp(sound.TimePosition/sound.TimeLength,0,1) or 0,1)
        end
    end
    flyTouch.Visible=state.fly and UIS.TouchEnabled
    if not state.fly then touchVertical=0 end
    local camera=workspace.CurrentCamera
    if camera and (camera~=lastCamera or camera.ViewportSize~=lastViewport) then
        lastCamera=camera; lastViewport=camera.ViewportSize; fit()
    end
    if state.fov and camera then
        if cameraOriginal[camera]==nil then cameraOriginal[camera]=camera.FieldOfView end
        camera.FieldOfView=state.fovValue
    end
    if spectating and camera then
        local h=spectating.Character and spectating.Character:FindFirstChildOfClass("Humanoid")
        if h then
            if not spectateOriginal[camera] then spectateOriginal[camera]={subject=camera.CameraSubject,kind=camera.CameraType} end
            camera.CameraSubject=h
        end
    end
    if state.fly and camera and flyObjects[1] and flyObjects[1].Parent then
        local h=humanoid()
        local direction=h and h.MoveDirection or Vector3.zero
        local up=touchVertical
        if not UIS:GetFocusedTextBox() then
            if UIS:IsKeyDown(Enum.KeyCode.Space) then up=up+1 end
            if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then up=up-1 end
        else direction=Vector3.zero end
        local velocity=Vector3.new(direction.X,up,direction.Z)
        if velocity.Magnitude>1 then velocity=velocity.Unit end
        flyObjects[1].VectorVelocity=velocity*state.flyValue
        local look=Vector3.new(camera.CFrame.LookVector.X,0,camera.CFrame.LookVector.Z)
        if look.Magnitude>0.01 then flyObjects[2].CFrame=CFrame.lookAt(Vector3.zero,look) end
    end
    frames=frames+1; fpsTime=fpsTime+dt; visualTimer=visualTimer+dt
    if fpsTime>=1 then
        dockClock.Text=os.date("%H:%M")
        local ok,ping=pcall(function() return player:GetNetworkPing()*1000 end)
        session.fps=math.floor(frames/fpsTime+0.5); session.ping=ok and math.floor(ping+0.5) or nil
        metrics.Text=string.format("%d FPS  /  %s ms",session.fps,session.ping and tostring(session.ping) or "--")
        if page=="Start" then updateDashboard() end
        frames=0; fpsTime=0
    end
    if visualTimer<0.25 then return end
    visualTimer=0
    local ownRoot=root()
    for _,other in ipairs(Players:GetPlayers()) do
        if other~=player then
            local char=other.Character
            local targetRoot=char and char:FindFirstChild("HumanoidRootPart")
            if highlights[other] and (not state.esp or highlights[other].Adornee~=char) then highlights[other]:Destroy(); highlights[other]=nil end
            if state.esp and char and not highlights[other] then
                highlights[other]=make("Highlight",{Name="ISBHighlight",Adornee=char,FillColor=C.accent,
                    FillTransparency=0.78,OutlineColor=C.text,OutlineTransparency=0.15,
                    DepthMode=Enum.HighlightDepthMode.AlwaysOnTop},char)
            end
            if tags[other] and (not state.names or tags[other].Adornee~=targetRoot) then tags[other]:Destroy(); tags[other]=nil end
            if state.names and targetRoot then
                if not tags[other] then
                    local tag=make("BillboardGui",{Name="ISBNametag",Adornee=targetRoot,AlwaysOnTop=true,
                        Size=UDim2.fromOffset(220,38),StudsOffset=Vector3.new(0,3.5,0)},gui)
                    local text=label(tag,"",12,C.text,UDim2.new(),UDim2.fromScale(1,1))
                    text.TextXAlignment=Enum.TextXAlignment.Center; text.TextStrokeTransparency=0.35
                    tags[other]=tag
                end
                local distance=ownRoot and math.floor((ownRoot.Position-targetRoot.Position).Magnitude) or 0
                tags[other]:FindFirstChildOfClass("TextLabel").Text=other.DisplayName .. "  ·  " .. distance .. " studs"
            end
        end
    end
end)
connect(player.CharacterRemoving,function()
    stopFly(); restoreCollisions()
    table.clear(originals)
end)
connect(player.CharacterAdded,function(char)
    task.spawn(function()
        local h=char:WaitForChild("Humanoid",10)
        if not alive or not h or player.Character~=char then return end
        applyMovement()
        if state.fly then char:WaitForChild("HumanoidRootPart",10); if alive and player.Character==char then startFly() end end
    end)
end)
refreshPlayers=function() if page=="Spieler" or page=="Start" then render() end end
connect(Players.PlayerAdded,refreshPlayers)
connect(Players.PlayerRemoving,function(other)
    if highlights[other] then highlights[other]:Destroy(); highlights[other]=nil end
    if tags[other] then tags[other]:Destroy(); tags[other]=nil end
    if spectating==other then restoreCamera() end
    task.defer(function() if alive then refreshPlayers() end end)
end)
local api = {}
api.Destroy = function()
    if not alive then return end
    alive=false; state.fly=false; state.noclip=false; state.fullbright=false; state.shadows=false
    for _,con in ipairs(connections) do con:Disconnect() end
    for _,con in ipairs(rowConnections) do con:Disconnect() end
    stopFly(); restoreCollisions(); clearVisuals(); applyLighting(); restoreCamera()
    for h,values in pairs(originals) do
        if h.Parent then
            if values.speedOwned then h.WalkSpeed=values.WalkSpeed end
            if values.jumpOwned then h.JumpPower=values.JumpPower; h.JumpHeight=values.JumpHeight end
        end
    end
    for camera,value in pairs(cameraOriginal) do if camera.Parent then camera.FieldOfView=value end end
    sound:Destroy(); backdropBlur:Destroy(); gui:Destroy()
    if env.ISBMenu==api then env.ISBMenu=nil end
end
-- Extend with your own client actions; callback errors are caught by the UI.
api.AddAction = function(id, category, name, description, callback)
    assert(type(id)=="string" and type(name)=="string" and type(callback)=="function", "Ungültige Aktion")
    assert(table.find(navNames,category) and category~="Start" and category~="Musik" and category~="Einstellungen", "Bewegung, Spieler oder Darstellung verwenden")
    for _,action in ipairs(actions) do assert(action.id~=id,"Aktions-ID bereits vorhanden") end
    addAction(id,category,name,tostring(description or ""),"button",callback)
    render()
end
api.Notify=notify
env.ISBMenu=api
task.spawn(function()
    if MarketplaceService then
        local ok,info=pcall(function() return MarketplaceService:GetProductInfo(game.PlaceId,Enum.InfoType.Asset) end)
        if alive and ok and type(info)=="table" then session.placeName=tostring(info.Name or session.placeName) end
    end
    local ok,friends=pcall(function() return Players:GetFriendsAsync(player.UserId) end)
    if ok and friends then
        local total=0
        repeat
            local good,entries=pcall(function() return friends:GetCurrentPage() end)
            if not good or not alive then break end
            for _,entry in ipairs(entries) do session.friends[entry.Id]=true; total=total+1 end
            if friends.IsFinished then session.friendTotal=total; break end
            local advanced=pcall(function() friends:AdvanceToNextPageAsync() end)
            if not advanced then break end
        until not alive
    end
    local good,online=pcall(function() return player:GetFriendsOnlineAsync(200) end)
    if alive and good and type(online)=="table" then session.onlineFriends=#online end
    if alive and page=="Start" then render() end
end)
connect(Players.PlayerAdded,function(other)
    if session.friends[other.UserId] then notify(other.DisplayName.." ist dem Server beigetreten.","Freund beigetreten","user-plus") end
    if table.find(CONFIG.StaffUserIds,other.UserId) then notify(other.DisplayName.." steht in deiner konfigurierten Staff-Liste.","Staff im Server","shield-check") end
end)
render()
window.GroupTransparency=1; motionScale.Scale=0.94; window.Visible=false
dock.GroupTransparency=1
animate(dock,{GroupTransparency=0})
task.delay(settings.reducedMotion and 0 or 0.3,function() if alive then setOpen(true) end end)
notify(CONFIG.Name .. " bereit • " .. CONFIG.ToggleKey.Name .. " öffnet das Menü")
return api
